INSERT INTO `services` VALUES (1,1,'Business Websites','business-websites','bi-building','A professional online presence for your shop, clinic, agency or small business.','A professional online presence for your shop, clinic, agency or small business.\n\nOdin\'s team in Colombo handles everything from planning to launch and after-sales support. We work with businesses all over Sri Lanka, explain everything in simple language, and stay with you after the project is finished.\n\nContact us for a free consultation and a clear, no-obligation quotation.','[\"Up to 8 pages, mobile friendly design\",\"Contact form, Google Maps & WhatsApp button\",\"Basic SEO so customers find you on Google\",\"Free domain (.lk \\/ .com) and hosting for 1 year\",\"Easy admin to update text and photos\"]',45000.00,'one-time','1 - 2 weeks',1,1,1,'2026-09-28 03:59:35','2026-09-28 03:59:35'),(2,1,'Corporate Websites','corporate-websites','bi-buildings','Premium multi-page websites for companies and organisations.','Premium multi-page websites for companies and organisations.\n\nOdin\'s team in Colombo handles everything from planning to launch and after-sales support. We work with businesses all over Sri Lanka, explain everything in simple language, and stay with you after the project is finished.\n\nContact us for a free consultation and a clear, no-obligation quotation.','[\"Custom design matched to your brand\",\"Unlimited pages with content management\",\"News, careers and downloads sections\",\"Multi-language support (English, Sinhala, Tamil)\",\"Performance and security hardening\"]',95000.00,'one-time','3 - 5 weeks',0,1,2,'2026-09-28 03:59:35','2026-09-28 03:59:35'),(3,1,'E-commerce Websites','e-commerce-websites','bi-cart3','Sell online with a complete store like Odin.lk — products, cart, checkout and orders.','Sell online with a complete store like Odin.lk — products, cart, checkout and orders.\n\nOdin\'s team in Colombo handles everything from planning to launch and after-sales support. We work with businesses all over Sri Lanka, explain everything in simple language, and stay with you after the project is finished.\n\nContact us for a free consultation and a clear, no-obligation quotation.','[\"Product catalogue with categories, brands and filters\",\"Cart, checkout and order tracking\",\"Cash on delivery, bank transfer and card payment gateways\",\"Admin panel for products, orders and customers\",\"Sales reports and visitor analytics\"]',150000.00,'one-time','4 - 8 weeks',1,1,3,'2026-09-28 03:59:35','2026-09-28 03:59:35'),(4,1,'Hotel & Restaurant Websites','hotel-restaurant-websites','bi-cup-hot','Show off rooms, menus and photos, and take bookings or orders online.','Show off rooms, menus and photos, and take bookings or orders online.\n\nOdin\'s team in Colombo handles everything from planning to launch and after-sales support. We work with businesses all over Sri Lanka, explain everything in simple language, and stay with you after the project is finished.\n\nContact us for a free consultation and a clear, no-obligation quotation.','[\"Room \\/ menu pages with photo galleries\",\"Online booking or table reservation form\",\"Food ordering with WhatsApp or online payments\",\"Reviews and TripAdvisor \\/ Google integration\",\"Promotions and seasonal offers\"]',75000.00,'one-time','2 - 4 weeks',0,1,4,'2026-09-28 03:59:35','2026-09-28 03:59:35'),(5,1,'Portfolio Websites','portfolio-websites','bi-person-badge','A stylish personal site for photographers, designers, freelancers and professionals.','A stylish personal site for photographers, designers, freelancers and professionals.\n\nOdin\'s team in Colombo handles everything from planning to launch and after-sales support. We work with businesses all over Sri Lanka, explain everything in simple language, and stay with you after the project is finished.\n\nContact us for a free consultation and a clear, no-obligation quotation.','[\"Beautiful gallery or project showcase\",\"About, services and testimonials sections\",\"Contact form and social media links\",\"Blazing fast one or two page layout\"]',30000.00,'one-time','1 week',0,1,5,'2026-09-28 03:59:35','2026-09-28 03:59:35'),(6,1,'Website Redesign','website-redesign','bi-brush','Give your old website a modern look, better speed and mobile support.','Give your old website a modern look, better speed and mobile support.\n\nOdin\'s team in Colombo handles everything from planning to launch and after-sales support. We work with businesses all over Sri Lanka, explain everything in simple language, and stay with you after the project is finished.\n\nContact us for a free consultation and a clear, no-obligation quotation.','[\"Fresh modern design, keeping your content\",\"Mobile and tablet friendly layout\",\"Speed and SEO improvements\",\"Move to faster, secure hosting if needed\"]',40000.00,'one-time','2 - 3 weeks',0,1,6,'2026-09-28 03:59:35','2026-09-28 03:59:35'),(7,1,'Website Maintenance','website-maintenance','bi-wrench-adjustable','We keep your website updated, secure, backed up and running smoothly.','We keep your website updated, secure, backed up and running smoothly.\n\nOdin\'s team in Colombo handles everything from planning to launch and after-sales support. We work with businesses all over Sri Lanka, explain everything in simple language, and stay with you after the project is finished.\n\nContact us for a free consultation and a clear, no-obligation quotation.','[\"Monthly updates and security patches\",\"Daily or weekly backups\",\"Content updates (text, images, prices)\",\"Uptime monitoring and quick fixes\",\"Monthly performance report\"]',5000.00,'per month','Ongoing',0,1,7,'2026-09-28 03:59:35','2026-09-28 03:59:35'),(8,1,'Landing Page Websites','landing-page-websites','bi-megaphone','A single high-converting page for campaigns, product launches and ads.','A single high-converting page for campaigns, product launches and ads.\n\nOdin\'s team in Colombo handles everything from planning to launch and after-sales support. We work with businesses all over Sri Lanka, explain everything in simple language, and stay with you after the project is finished.\n\nContact us for a free consultation and a clear, no-obligation quotation.','[\"Eye-catching one page design\",\"Lead capture form connected to email \\/ WhatsApp\",\"Facebook & Google Ads tracking set up\",\"Fast loading for better ad results\"]',25000.00,'one-time','3 - 5 days',0,1,8,'2026-09-28 03:59:35','2026-09-28 03:59:35'),(9,1,'Custom Software Development','custom-software-development','bi-code-slash','Software built exactly for your business — web apps, portals and automation.','Software built exactly for your business — web apps, portals and automation.\n\nOdin\'s team in Colombo handles everything from planning to launch and after-sales support. We work with businesses all over Sri Lanka, explain everything in simple language, and stay with you after the project is finished.\n\nContact us for a free consultation and a clear, no-obligation quotation.','[\"Requirement study and free consultation\",\"Web-based system accessible from anywhere\",\"User roles, reports and data export\",\"Integration with your existing tools\",\"Training, documentation and support\"]',NULL,'quotation','Depends on scope',1,1,9,'2026-09-28 03:59:35','2026-09-28 03:59:35'),(10,2,'Sales Management','sales-management','bi-receipt','Quotations, invoices, POS billing and sales tracking.','Quotations, invoices, POS billing and sales tracking.\n\nOdin\'s team in Colombo handles everything from planning to launch and after-sales support. We work with businesses all over Sri Lanka, explain everything in simple language, and stay with you after the project is finished.\n\nContact us for a free consultation and a clear, no-obligation quotation.','[\"Quotations, invoices and receipts\",\"POS billing with barcode scanner\",\"Customer credit limits and outstanding tracking\",\"Sales by product, customer and salesperson\"]',75000.00,'one-time','2 - 3 weeks',1,1,1,'2026-09-28 03:59:35','2026-09-28 03:59:35'),(11,2,'Inventory Management','inventory-management','bi-box-seam','Know exactly what stock you have, where it is and when to reorder.','Know exactly what stock you have, where it is and when to reorder.\n\nOdin\'s team in Colombo handles everything from planning to launch and after-sales support. We work with businesses all over Sri Lanka, explain everything in simple language, and stay with you after the project is finished.\n\nContact us for a free consultation and a clear, no-obligation quotation.','[\"Real-time stock levels across locations\",\"Barcode and serial \\/ IMEI number tracking\",\"Low stock alerts and reorder levels\",\"Stock transfers, adjustments and valuation\"]',75000.00,'one-time','2 - 3 weeks',0,1,2,'2026-09-28 03:59:35','2026-09-28 03:59:35'),(12,2,'Purchasing','purchasing','bi-bag-check','Purchase orders, goods received notes and supplier bills.','Purchase orders, goods received notes and supplier bills.\n\nOdin\'s team in Colombo handles everything from planning to launch and after-sales support. We work with businesses all over Sri Lanka, explain everything in simple language, and stay with you after the project is finished.\n\nContact us for a free consultation and a clear, no-obligation quotation.','[\"Purchase requests and approvals\",\"Purchase orders and GRN\",\"Supplier invoices and returns\",\"Purchase history and price comparison\"]',60000.00,'one-time','2 weeks',0,1,3,'2026-09-28 03:59:35','2026-09-28 03:59:35'),(13,2,'Accounting','accounting','bi-calculator','Double-entry accounting with Sri Lankan tax support.','Double-entry accounting with Sri Lankan tax support.\n\nOdin\'s team in Colombo handles everything from planning to launch and after-sales support. We work with businesses all over Sri Lanka, explain everything in simple language, and stay with you after the project is finished.\n\nContact us for a free consultation and a clear, no-obligation quotation.